using System.IO;
using System.Text.Json;
using System.Security.Cryptography;
using System.Windows;
namespace DanceStudio;
public static class ContentTests {
 public static void Run(string input,string output){Directory.CreateDirectory(output);int checks=0;void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}var p=SongProject.Load(input);var rig=Rig.Load(p.Skeleton);var dance=MotionClip.Load(p.Dance.Path,p.Dance.HkxBindingIndex,p.Dance.IdentityRigProof);var camera=MotionClip.Load(p.Camera.Path,p.Camera.HkxBindingIndex,p.Camera.IdentityRigProof);var audio=AudioImport.Load(p.Audio.Path);p.CameraBone=97;p.ExportIn=30;p.ExportOut=31.03;var packages=new List<string>();
  foreach(var kind in new[]{"both","dance","camera"}){p.Id="same-project";p.Title="Same title";string folder=GameExporter.Export(output,p,kind=="camera"?null:dance,kind=="dance"?null:camera,audio,rig);packages.Add(folder);using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(folder,"song.json")));var j=doc.RootElement;Check(j.GetProperty("schemaVersion").GetInt32()==4,"new runtime schema");Check(j.TryGetProperty("dance",out _)==(kind!="camera"),"optional dance metadata");Check(j.TryGetProperty("cameraSamples",out _)==(kind!="dance"),"optional camera metadata");Check(File.Exists(Path.Combine(folder,"config.json"))==(kind!="camera"),"OAR only for dance");Check(!Directory.GetFiles(folder,"*",SearchOption.AllDirectories).Any(x=>x.EndsWith(".danceproj")||x.EndsWith(".txt")||x.EndsWith(".md")||x.Contains("Diagnostics")),"runtime files only");foreach(var h in j.GetProperty("hashes").EnumerateObject()){Check(Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(Path.Combine(folder,h.Name))))==h.Value.GetString(),"runtime asset hash");}Check(Math.Abs(WaveAudio.Load(Path.Combine(folder,"music.wav")).Duration-1.03)<1.0/audio.SampleRate,"audio master duration");}
  p.PackageIds["camera"]="camera-short";p.ExportOut=30.5;packages.Add(GameExporter.Export(output,p,null,camera,audio,rig));p.ExportOut=31.03;
  string id=p.PackageId(true,false);string repeat=GameExporter.Export(output,p,dance,null,audio,rig);using(var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(repeat,"song.json"))))Check(doc.RootElement.GetProperty("id").GetString()==id,"reexport retains package ID");
  string independent=GameExporter.Export(output,p,dance,null,audio,rig,true);using(var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(independent,"song.json"))))Check(doc.RootElement.GetProperty("id").GetString()!=id,"new independent package ID");
  File.WriteAllText(Path.Combine(output,"revisions.json"),JsonSerializer.Serialize(new[]{repeat,independent},SongProject.Json));
  var ids=packages.Take(3).Select(x=>JsonDocument.Parse(File.ReadAllText(Path.Combine(x,"song.json"))).RootElement.GetProperty("id").GetString()).ToArray();Check(ids.Distinct().Count()==3&&!ids.Contains(p.Id),"same project separate kind IDs");
  string saved=Path.Combine(output,"identity.danceproj");p.Save(saved);var loaded=SongProject.Load(saved);Check(loaded.Id==p.Id&&loaded.PackageIds.OrderBy(x=>x.Key).SequenceEqual(p.PackageIds.OrderBy(x=>x.Key)),"identity save roundtrip");
  string diagnostic=Exporter.Export(output,p,dance,null,audio,rig);Check(!File.Exists(Path.Combine(diagnostic,"source.danceproj"))&&!File.Exists(Path.Combine(diagnostic,"README-KO.txt")),"editor export excludes project and instructions");
  bool rejected=false;try{GameExporter.Export(output,p,null,null,audio,rig);}catch(InvalidDataException){rejected=true;}Check(rejected,"empty package rejected");
  string alias=Path.Combine(output,"real-wave.wxm");File.Copy(Path.Combine(packages[0],"music.wav"),alias,true);Check(AudioImport.Load(alias).Frames==WaveAudio.Load(alias).Frames,"actual content detection wxm alias");string bad=Path.Combine(output,"bad.xwm");File.WriteAllText(bad,"this is not audio");rejected=false;try{AudioImport.Load(bad);}catch(InvalidDataException){rejected=true;}Check(rejected,"fake xwm rejected");
  var app=Application.Current??new Application();var track=new TrackEdit{Path="test.hkx",In=2,Out=22,Start=10,Speed=2};var timeline=new TimelineView{Project=new SongProject{Dance=track},Span=60,Playhead=5};timeline.Measure(new Size(1200,246));timeline.Arrange(new Rect(0,0,1200,246));double width=1050;double X(double t)=>132+t/60*width;double sought=-1;int edits=0;timeline.Seek=t=>{sought=t;timeline.Playhead=t;};timeline.Edited=()=>edits++;timeline.PointerDown(new Point(X(15),55));timeline.PointerMove(new Point(X(19),55),true);timeline.CancelDrag();Check(track.Start==14&&track.In==2&&track.Out==22&&track.Speed==2,"body drag edits Start only");Check(edits>0,"live drag notification");timeline.PointerDown(new Point(X(19),55));timeline.PointerMove(new Point(-100,55),true);timeline.CancelDrag();Check(track.Start>=0&&track.In==2&&track.Out==22,"left drag bound");timeline.PointerDown(new Point(X(20),10));timeline.PointerMove(new Point(X(30),10),true);timeline.CancelDrag();Check(Math.Abs(sought-30)<1e-10,"header/playhead continuous scrub");timeline.PointerDown(new Point(X(30),100));timeline.PointerMove(new Point(X(35),100),true);timeline.CancelDrag();Check(Math.Abs(sought-35)<1e-10,"playhead drag over tracks");
  timeline.Project=new SongProject{Dance=track};track.In=2;track.Out=22;track.Start=10;timeline.Playhead=50;
  timeline.PointerDown(new Point(X(10),55));timeline.PointerMove(new Point(X(11),55),true);timeline.CancelDrag();Check(track.In==4&&track.Out==22&&track.Start==11&&track.Speed==2,"left edge trimming retains source mapping");
  timeline.SourceDurations=[30,0,0];timeline.PointerDown(new Point(X(track.TimelineEnd),55));timeline.PointerMove(new Point(X(track.TimelineEnd+2),55),true);timeline.CancelDrag();Check(track.Out==26&&track.In==4&&track.Start==11,"right edge trimming remains operational");
  var removal=new SongProject{Dance=new(){Path="dance.hkx",Out=20},Camera=new(){Path="camera.hkx",Out=20},Audio=new(){Path="music.wav",Out=20}};timeline.Project=removal;timeline.Playhead=50;timeline.RemoveTrack=i=>removal.RemoveTrack(i);
  Check(timeline.TrackMenu(new Point(X(25),55))==null&&timeline.TrackMenu(new Point(X(5),34))==null,"empty right click has no menu");
  for(int i=0;i<3;i++){double before=sought;var menu=timeline.TrackMenu(new Point(X(5),55+i*58));Check(menu!=null,"actual track context menu");var item=(System.Windows.Controls.MenuItem)menu!.Items[0];Check((string)item.Header=="트랙 삭제","context label");item.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.MenuItem.ClickEvent));Check(new[]{removal.Dance,removal.Camera,removal.Audio}[i].Path==""&&before==sought,"context delete only target without seek");Check(timeline.TrackMenu(new Point(X(5),55+i*58))==null,"removed track no context");}
  string empty=Path.Combine(output,"empty.danceproj");removal.Save(empty);var emptyLoaded=SongProject.Load(empty);Check(new[]{emptyLoaded.Dance,emptyLoaded.Camera,emptyLoaded.Audio}.All(x=>x.Path==""),"empty tracks save roundtrip");
  File.WriteAllText(Path.Combine(output,"packages.json"),JsonSerializer.Serialize(packages,SongProject.Json));File.WriteAllText(Path.Combine(output,"validation.json"),JsonSerializer.Serialize(new{passed=true,checks,packageKinds=3,xwmDecoderTested=false,gameTested=false},SongProject.Json));
 }
}
